package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sync/atomic"
	"time"
)

// ================================================================
// JSON-RPC 2.0 Types
// ================================================================

type JSONRPCRequest struct {
	JSONRPC string      `json:"jsonrpc"`
	ID      int64       `json:"id,omitempty"`
	Method  string      `json:"method"`
	Params  interface{} `json:"params,omitempty"`
}

type JSONRPCResponse struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      int64           `json:"id"`
	Result  json.RawMessage `json:"result,omitempty"`
	Error   *JSONRPCError   `json:"error,omitempty"`
}

type JSONRPCError struct {
	Code    int             `json:"code"`
	Message string          `json:"message"`
	Data    json.RawMessage `json:"data,omitempty"`
}

// ================================================================
// MCP-Specific Types
// ================================================================

type InitializeParams struct {
	ProtocolVersion string         `json:"protocolVersion"`
	Capabilities    map[string]any `json:"capabilities"`
	ClientInfo      ClientInfo     `json:"clientInfo"`
}

type ClientInfo struct {
	Name    string `json:"name"`
	Version string `json:"version"`
}

type ToolCallParams struct {
	Name      string         `json:"name"`
	Arguments map[string]any `json:"arguments"`
}

type ToolResult struct {
	Content []ToolContent `json:"content"`
	IsError bool          `json:"isError,omitempty"`
}

type ToolContent struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

type ToolDefinition struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"inputSchema"`
}

type ToolsListResult struct {
	Tools []ToolDefinition `json:"tools"`
}

// ================================================================
// MCP Client
// ================================================================

type MCPClient struct {
	endpoint   string
	sessionID  string
	httpClient *http.Client
	nextID     atomic.Int64
}

func NewMCPClient(endpoint string) *MCPClient {
	return &MCPClient{
		endpoint: endpoint,
		httpClient: &http.Client{
			Timeout: 30 * time.Second,
			Transport: &http.Transport{
				MaxIdleConns:        100,
				MaxIdleConnsPerHost: 100,
				IdleConnTimeout:     90 * time.Second,
			},
		},
	}
}

func (c *MCPClient) sendRequest(method string, params interface{}) (*JSONRPCResponse, time.Duration, error) {
	id := c.nextID.Add(1)

	req := JSONRPCRequest{
		JSONRPC: "2.0",
		ID:      id,
		Method:  method,
		Params:  params,
	}

	body, err := json.Marshal(req)
	if err != nil {
		return nil, 0, fmt.Errorf("marshal request: %w", err)
	}

	httpReq, err := http.NewRequest("POST", c.endpoint, bytes.NewReader(body))
	if err != nil {
		return nil, 0, fmt.Errorf("create http request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Accept", "application/json")
	if c.sessionID != "" {
		httpReq.Header.Set("Mcp-Session-Id", c.sessionID)
	}

	start := time.Now()
	httpResp, err := c.httpClient.Do(httpReq)
	elapsed := time.Since(start)

	if err != nil {
		return nil, elapsed, fmt.Errorf("http request: %w", err)
	}
	defer httpResp.Body.Close()

	// Capture session ID from first response
	if sid := httpResp.Header.Get("Mcp-Session-Id"); sid != "" && c.sessionID == "" {
		c.sessionID = sid
	}

	respBody, err := io.ReadAll(httpResp.Body)
	if err != nil {
		return nil, elapsed, fmt.Errorf("read response: %w", err)
	}

	if httpResp.StatusCode != 200 {
		return nil, elapsed, fmt.Errorf("http status %d: %s", httpResp.StatusCode, string(respBody))
	}

	var resp JSONRPCResponse
	if err := json.Unmarshal(respBody, &resp); err != nil {
		return nil, elapsed, fmt.Errorf("unmarshal response: %w", err)
	}

	if resp.Error != nil {
		return &resp, elapsed, fmt.Errorf("jsonrpc error %d: %s", resp.Error.Code, resp.Error.Message)
	}

	return &resp, elapsed, nil
}

func (c *MCPClient) sendNotification(method string, params interface{}) error {
	req := JSONRPCRequest{
		JSONRPC: "2.0",
		Method:  method,
		Params:  params,
	}

	body, err := json.Marshal(req)
	if err != nil {
		return fmt.Errorf("marshal notification: %w", err)
	}

	httpReq, err := http.NewRequest("POST", c.endpoint, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("create http request: %w", err)
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Accept", "application/json")
	if c.sessionID != "" {
		httpReq.Header.Set("Mcp-Session-Id", c.sessionID)
	}

	httpResp, err := c.httpClient.Do(httpReq)
	if err != nil {
		return fmt.Errorf("http request: %w", err)
	}
	httpResp.Body.Close()
	return nil
}

// ================================================================
// MCP Session Lifecycle
// ================================================================

func (c *MCPClient) Initialize() (*JSONRPCResponse, time.Duration, error) {
	resp, dur, err := c.sendRequest("initialize", InitializeParams{
		ProtocolVersion: "2025-11-25",
		Capabilities:    map[string]any{},
		ClientInfo: ClientInfo{
			Name:    "mcp-benchmark-harness",
			Version: "1.0.0",
		},
	})
	if err != nil {
		return nil, dur, fmt.Errorf("initialize: %w", err)
	}

	if notifErr := c.sendNotification("notifications/initialized", nil); notifErr != nil {
		return nil, dur, fmt.Errorf("initialized notification: %w", notifErr)
	}

	return resp, dur, nil
}

func (c *MCPClient) ListTools() (*ToolsListResult, time.Duration, error) {
	resp, dur, err := c.sendRequest("tools/list", nil)
	if err != nil {
		return nil, dur, err
	}

	var result ToolsListResult
	if err := json.Unmarshal(resp.Result, &result); err != nil {
		return nil, dur, fmt.Errorf("unmarshal tools list: %w", err)
	}
	return &result, dur, nil
}

func (c *MCPClient) CallTool(toolName string, args map[string]any) (*ToolResult, time.Duration, error) {
	resp, dur, err := c.sendRequest("tools/call", ToolCallParams{
		Name:      toolName,
		Arguments: args,
	})
	if err != nil {
		return nil, dur, err
	}

	var result ToolResult
	if err := json.Unmarshal(resp.Result, &result); err != nil {
		return nil, dur, fmt.Errorf("unmarshal tool result: %w", err)
	}

	if result.IsError {
		errMsg := "unknown error"
		if len(result.Content) > 0 {
			errMsg = result.Content[0].Text
		}
		return &result, dur, fmt.Errorf("tool error: %s", errMsg)
	}

	return &result, dur, nil
}

// ================================================================
// Convenience Methods
// ================================================================

func (c *MCPClient) ListServices() (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_list_services", map[string]any{})
}

func (c *MCPClient) ListTables(service string) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_list_tables", map[string]any{
		"service": service,
	})
}

func (c *MCPClient) DescribeTable(service, table string) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_describe_table", map[string]any{
		"service": service,
		"table":   table,
	})
}

func (c *MCPClient) Query(service, table string, opts map[string]any) (*ToolResult, time.Duration, error) {
	args := map[string]any{
		"service": service,
		"table":   table,
	}
	for k, v := range opts {
		args[k] = v
	}
	return c.CallTool("faucet_query", args)
}

func (c *MCPClient) Insert(service, table string, records []map[string]any) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_insert", map[string]any{
		"service": service,
		"table":   table,
		"records": records,
	})
}

func (c *MCPClient) Update(service, table, filter string, record map[string]any) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_update", map[string]any{
		"service": service,
		"table":   table,
		"filter":  filter,
		"record":  record,
	})
}

func (c *MCPClient) Delete(service, table, filter string) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_delete", map[string]any{
		"service": service,
		"table":   table,
		"filter":  filter,
	})
}

func (c *MCPClient) RawSQL(service, sql string) (*ToolResult, time.Duration, error) {
	return c.CallTool("faucet_raw_sql", map[string]any{
		"service": service,
		"sql":     sql,
		"limit":   1000,
	})
}

#!/bin/bash
set -euo pipefail
echo "=== PostgreSQL 18 Optimization ==="
echo "Reference: https://www.postgresql.org/docs/17/performance-tips.html"
echo ""

PSQL="docker exec bench-postgres psql -U bench -d benchmark"

# Step 1: Create all 10 logical indexes (v5 blueprint Section 8)
echo "[1/4] Adding indexes..."
$PSQL <<'SQL'
CREATE INDEX IF NOT EXISTS idx_orders_customer_id ON orders(customer_id);
CREATE INDEX IF NOT EXISTS idx_orders_status_date ON orders(status, order_date);
CREATE INDEX IF NOT EXISTS idx_order_items_order_id ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_order_items_product_id ON order_items(product_id);
CREATE INDEX IF NOT EXISTS idx_reviews_product_id ON reviews(product_id);
CREATE INDEX IF NOT EXISTS idx_reviews_customer_id ON reviews(customer_id);
CREATE INDEX IF NOT EXISTS idx_reviews_rating ON reviews(product_id, rating);
CREATE INDEX IF NOT EXISTS idx_products_category ON products(category_id, is_active);
CREATE INDEX IF NOT EXISTS idx_addresses_customer ON addresses(customer_id);
CREATE INDEX IF NOT EXISTS idx_inventory_product ON inventory(product_id);
SQL
echo "  10 indexes created (IF NOT EXISTS)"

# Step 2: Apply tuning via ALTER SYSTEM and restart
echo ""
echo "[2/4] Applying tuning via ALTER SYSTEM and restarting..."
$PSQL <<'SQL'
ALTER SYSTEM SET shared_buffers = '2GB';
ALTER SYSTEM SET effective_cache_size = '6GB';
ALTER SYSTEM SET work_mem = '64MB';
ALTER SYSTEM SET maintenance_work_mem = '512MB';
ALTER SYSTEM SET wal_buffers = '64MB';
ALTER SYSTEM SET checkpoint_completion_target = 0.9;
ALTER SYSTEM SET max_wal_size = '2GB';
ALTER SYSTEM SET random_page_cost = 1.1;
ALTER SYSTEM SET effective_io_concurrency = 200;
ALTER SYSTEM SET default_statistics_target = 200;
ALTER SYSTEM SET max_parallel_workers_per_gather = 2;
ALTER SYSTEM SET max_parallel_workers = 4;
ALTER SYSTEM SET max_worker_processes = 8;
ALTER SYSTEM SET max_connections = 200;
SQL
echo "  Tuning applied via ALTER SYSTEM"
docker restart bench-postgres
sleep 5
echo "  PostgreSQL restarted with tuning"

# Step 3: Run ANALYZE on all tables
echo ""
echo "[3/4] Running ANALYZE on all tables..."
$PSQL -c "ANALYZE;"
echo "  ANALYZE complete"

# Step 4: Verify indexes
echo ""
echo "[4/4] Verifying indexes..."
$PSQL -c "
SELECT schemaname, tablename, indexname
FROM pg_indexes
WHERE schemaname = 'public'
  AND indexname LIKE 'idx_%'
ORDER BY tablename, indexname;
"

echo ""
echo "=== PostgreSQL 18 optimization complete ==="
